namespace ghidra.feature.fid.plugin;




using ghidra.feature.fid.db;
using ghidra.feature.fid.service;
using ghidra.framework.model;
using ghidra.framework.model;
using ghidra.program.database;
using ghidra.program.model.lang;
using ghidra.program.model.mem;
using ghidra.program.util;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;
using ghidra.util.task;

/**
 * Inner class that implements the ingest task.
 */
public class IngestTask : Task {
	private FidFile fidFile;
	private LibraryRecord libraryRecord;
	protected DomainFolder folder;
	protected string libraryFamilyName;
	protected string libraryVersion;
	protected string libraryVariant;
	private FidFilter programFilter;
	private File commonSymbolsFile;
	private FidService fidService;
	private FidPopulateResultReporter reporter;

	public IngestTask(string title, FidFile fidFile, LibraryRecord libraryRecord,
			DomainFolder folder, string libraryFamilyName, string libraryVersion,
			string libraryVariant, FidFilter programFilter, File commonSymbolsFile,
			FidService fidService, FidPopulateResultReporter reporter)
    : base(title, true, false, false, false)
    {
		this.fidFile = fidFile;
		this.libraryRecord = libraryRecord;
		this.folder = folder;
		this.libraryFamilyName = libraryFamilyName;
		this.libraryVersion = libraryVersion;
		this.libraryVariant = libraryVariant;
		this.commonSymbolsFile = commonSymbolsFile;
		this.fidService = fidService;
		this.reporter = reporter;
		this.programFilter = programFilter;
		checkArgumentValidity();
	}

	private void checkArgumentValidity()
    {
		if (libraryFamilyName == null || libraryFamilyName.isBlank()) {
			throw new IllegalArgumentException("Library Family Name is empty");
		}
		if (libraryVersion == null || libraryVersion.isBlank()) {
			throw new IllegalArgumentException("Library Version is empty");
		}
		if (libraryVariant == null || libraryVariant.isBlank()) {
			throw new IllegalArgumentException("Library Variant is empty");
		}
		LanguageID languageId = programFilter.getLanguageID();
		if (languageId == null) {
			throw new IllegalArgumentException("Language is empty");
		}
		LanguageService languageService = DefaultLanguageService.getLanguageService();
		LanguageDescription language = languageService.getLanguageDescription(languageId);
		Set<CompilerSpecID> compilerSpecs = programFilter.getCompilerSpecs(languageId);
		if (compilerSpecs != null) {
			foreach (CompilerSpecID id in compilerSpecs) {
				language.getCompilerSpecDescriptionByID(id);	// Verify spec is present
			}
		}
		if (commonSymbolsFile != null && !commonSymbolsFile.isFile()) {
			throw new IllegalArgumentException(
				"Common Symbols File: " + commonSymbolsFile.getName() + " does not exist");
		}
	}

	/* @Override */
	public void run(TaskMonitor monitor) {

		FidDB fidDb = null;
		try {
			fidDb = fidFile.getFidDB(true);
		}
		catch (VersionException e) {
			// Version upgrades are not supported
			Msg.showError(this, null, "Failed to open FidDb",
				"Failed to open incompatible FidDb (may need to regenerate with this version of Ghidra): " +
					fidFile.getPath());
			return;
		}
		catch (IOException e) {
			Msg.showError(this, null, "Failed to open FidDb",
				"Failed to open FidDb: " + fidFile.getPath(), e);
			return;
		}

		try {
			List<string> commonSymbols = parseSymbols(monitor);
			List<DomainFile> programs = new List<DomainFile>();
			monitor.setMessage("Finding domain files...");
			monitor.setIndeterminate(true);
			findPrograms(programs, folder, monitor);
			monitor.setIndeterminate(false);

			monitor.setMessage("Populating library...");
			FidPopulateResult result = fidService.createNewLibraryFromPrograms(fidDb,
				libraryFamilyName, libraryVersion, libraryVariant, programs, null, programFilter,
				libraryRecord == null ? null : Arrays.asList(libraryRecord), commonSymbols,
				monitor);
			reporter.report(result);
			fidDb.saveDatabase("Saving", monitor);
		}
		catch (CancelledException e) {
			// cancelled by user; don't notify
		}
		catch (MemoryAccessException e) {
			Msg.showError(this, null, "Unexpected memory access exception",
				"Please notify the Ghidra team:", e);
		}
		catch (VersionException e) {
			Msg.showError(this, null, "Version Exception",
				"One of the programs in your domain folder cannot be upgraded: " + e.getMessage());
		}
		catch (IOException e) {
			Msg.showError(this, null, "FidDb IOException", "Please notify the Ghidra team:", e);
		}
		finally {
			fidDb.close();
		}

	}

	private List<string> parseSymbols(TaskMonitor monitor)
    {
		if (commonSymbolsFile == null) {
			return null;
		}
		BufferedReader reader = new BufferedReader(new FileReader(commonSymbolsFile));
		LinkedList<string> res = new LinkedList<string>();
		string line = reader.readLine();
		while (line != null) {
			monitor.checkCancelled();
			if (line.length() != 0) {
				res.add(line);
			}
			line = reader.readLine();
		}
		reader.close();
		return res;
	}

	/**
	 * Recursively finds all domain objects that are program files under a domain folder.
	 * @param programs the "return" value; found programs are placed in this collection
	 * @param myFolder the domain folder to search
	 * @param monitor a task monitor
	 * @throws CancelledException if the user cancels
	 */
	protected void findPrograms(List<DomainFile> programs, DomainFolder myFolder,
			TaskMonitor monitor)
    {
		if (myFolder == null) {
			return;
		}
		DomainFile[] files = myFolder.getFiles();
		foreach (DomainFile domainFile in files) {
			monitor.checkCancelled();
			monitor.incrementProgress(1);
			// Do not follow folder-links or consider program links.  Using content type
			// to filter is best way to control this.  If program links should be considered
			// "Program.class.isAssignableFrom(domainFile.getDomainObjectClass())"
			// should be used.
			if (domainFile.getContentType().equals(ProgramContentHandler.PROGRAM_CONTENT_TYPE)) {
				programs.add(domainFile);
			}
		}
		DomainFolder[] folders = myFolder.getFolders();
		foreach (DomainFolder domainFolder in folders) {
			monitor.checkCancelled();
			monitor.incrementProgress(1);
			findPrograms(programs, domainFolder, monitor);
		}
	}
}
